import{z as d,x as l,o as A,c as S,q as o,j as n,D as e,d as E,s as r,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"SAML","description":"","frontmatter":{"title":"SAML","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saml.md","filePath":"cs/saml.md","lastUpdated":1791413859000}'),p={name:"cs/saml.md"};function B(c,a,P,h,u,C){const t=l("Mermaid");return A(),S("div",null,[a[2]||(a[2]=o('<h1 id="saml" tabindex="-1">SAML <a class="header-anchor" href="#saml" aria-label="Permalink to &quot;SAML&quot;">​</a></h1><div class="epigraph"><p>SAML 用 XML 断言在身份提供者与服务提供者之间搬家。签名包络、受众、时间窗与「谁解析 XML」决定断言是否可被换皮。</p><footer>—— OASIS SAML 2.0；对照 RFC 7522 等承载轮廓；Gross 与 Pfitzmann 对联邦的讨论</footer></div><p>上一课<a href="/cs/oauth-attack-surface">OAuth</a>是 JSON/REST 世界的联邦近亲。缺口是<strong>企业 SSO 仍大量走 SAML</strong>：浏览器 POST 一份 XML 断言回来。本课收验证合同——收到断言后必须检查什么，不给 XML 包装攻击的操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典失败清单：签名验证的不是被解析使用的那一块（XML 包装）；解析器允许外部实体（XXE）；Audience 为空或过宽，断言被任何 SP 换皮重用；时钟窗过大，过期断言长命；SP 不验 <code>InResponseTo</code>，响应可被注入别的会话。缺口是 XML 安全与断言语义两层都要收紧，不是再讲联邦单点登录的商业故事。</p><h3 id="与-oidc-并存" tabindex="-1">与 OIDC 并存 <a class="header-anchor" href="#与-oidc-并存" aria-label="Permalink to &quot;与 OIDC 并存&quot;">​</a></h3><p>同一组织常常 SAML 与 OIDC 并存，甚至两套 IdP。应用要钉死一种验证库与一套配置，所有断言走同一校验路径；「收到断言就建会话」等价于不设防。</p><p><span class="marginnote">SAML 2.0 Core。XML 数字签名与包装是经典失败模式——只陈述「验签树必须等于解析树」。本课禁止利用指导。</span></p><p><span class="marginnote">「断言」就是 IdP 签过名的一句话陈述：主体是谁、什么时间窗内有效、发给哪个受众。SP 信任的不是这句话本身，而是 IdP 的签名——所以签名覆盖的范围若和 SP 实际读取的字段不一致，攻击面就出现在那道缝里。</span></p><p><span class="marginnote">常见误区：初学者容易以为「XML 有签名就安全」。实际上签名只保证「签过的那一段没被改」，不保证「你解析到的就是签过的那一段」；XML 允许同一文档有多种解析视图，验签树和解析树一旦分叉，签名就形同虚设。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SP 发起的流程：SP 把用户 Redirect 到 IdP，IdP 认证后让浏览器 POST 签名断言回来。必验清单固定五项：签名且验签树等于解析树、Issuer 是已知 IdP、Audience 是本 SP、Conditions 时间窗有效、Subject 与 <code>InResponseTo</code> 对得上本会话。对照 JWT：同是声明集合，编码与信任解析不同。</p>',13)),(A(),n(i,null,{default:e(()=>[r(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E6%9C%8D%E5%8A%A1%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%20--%3E%20IDP%5B%22%E8%BA%AB%E4%BB%BD%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%0A%20%20IDP%20--%3E%20ASS%5B%22%E5%B8%A6%E7%AD%BE%E6%96%AD%E8%A8%80%22%5D%0A%20%20ASS%20--%3E%20V%5B%22%E9%AA%8C%E7%AD%BE%E6%A0%91%3D%E8%A7%A3%E6%9E%90%E6%A0%91%22%5D%0A%20%20V%20--%3E%20SESS%5B%22%E5%BB%BA%20SP%20%E4%BC%9A%E8%AF%9D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"机制上，联邦把用户口令从各 SP 拿走、集中到 IdP，但 TCB 没有变小，只是换成了 IdP 加整个 XML 签名解析栈：口令泄漏面缩小，断言伪造面换了个位置，验证合同因此要逐项钉死。下一课 WebAuthn：把密钥放到认证器，减少共享口令与断言解析面。",-1)),(A(),n(i,null,{default:e(()=>[r(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%20POST%20%E6%96%AD%E8%A8%80%E5%88%B0%20SP%22%5D%20--%3E%20C1%7B%22%E9%AA%8C%E7%AD%BE%E6%A0%91%20%3D%20%E8%A7%A3%E6%9E%90%E6%A0%91%3F%22%7D%0A%20%20C1%20--%20%22%E5%90%A6%22%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%22%5D%0A%20%20C1%20--%20%22%E6%98%AF%22%20--%3E%20C2%7B%22Issuer%20%E6%98%AF%E5%B7%B2%E7%9F%A5%20IdP%3F%22%7D%0A%20%20C2%20--%20%22%E5%90%A6%22%20--%3E%20REJ%0A%20%20C2%20--%20%22%E6%98%AF%22%20--%3E%20C3%7B%22Audience%20%E6%98%AF%E6%9C%AC%20SP%3F%22%7D%0A%20%20C3%20--%20%22%E5%90%A6%22%20--%3E%20REJ%0A%20%20C3%20--%20%22%E6%98%AF%22%20--%3E%20C4%7B%22%E6%97%B6%E9%97%B4%E7%AA%97%E6%9C%89%E6%95%88%3F%22%7D%0A%20%20C4%20--%20%22%E5%90%A6%22%20--%3E%20REJ%0A%20%20C4%20--%20%22%E6%98%AF%22%20--%3E%20C5%7B%22InResponseTo%20%E5%AF%B9%E4%B8%8A%E6%9C%AC%E4%BC%9A%E8%AF%9D%3F%22%7D%0A%20%20C5%20--%20%22%E5%90%A6%22%20--%3E%20REJ%0A%20%20C5%20--%20%22%E6%98%AF%22%20--%3E%20SESS%5B%22%E5%BB%BA%E4%BC%9A%E8%AF%9D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>这张图回答的问题是：一份断言从落地到建会话，要连续穿过哪五道闸门——任何一道放空（Audience 为空、时钟窗过大、不验 <code>InResponseTo</code>），假断言或旧断言就能从那个缺口钻进会话。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 Bindings，Artifact、SOAP 等从略。WebAuthn/FIDO2 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OAuth 之外，SAML 是企业 SSO 常用的 XML 断言联邦。</li><li>签名覆盖必须对准实际解析的断言，验签树等于解析树。</li><li>受众与时间窗不可空转，<code>InResponseTo</code> 要回对会话。</li><li>下一课 WebAuthn / FIDO2。</li><li>出处：OASIS SAML 2.0；对照 OWASP 对 SAML 的讨论；Anderson。</li></ul>',5))])}const I=d(p,[["render",B]]);export{m as __pageData,I as default};
